// src/components/Sidebar.jsx
import React from 'react';
import { Link } from 'react-router-dom';
import './Sidebar.css';

function Sidebar() {
  return (
    <aside className="sidebar">
      <h3 className="sidebar-title">תפריט</h3>
      <nav className="sidebar-nav">
        <Link to="/">דף הבית</Link>
        <Link to="/report1">דוח 1</Link>
        <Link to="/report2">דוח 2</Link>
        <Link to="/report3">דוח 3</Link>
        <Link to="/report4">דוח 4</Link>
        <Link to="/report5">דוח 5</Link>
      </nav>
    </aside>
  );
}

export default Sidebar;
